239 :         // evaluate the function at the starting point and calculate its norm
240 :         updateResidualsAndCost();
241 : 
242 :         // outer loop
243 :         lmPar = 0;
244 :         boolean firstIteration = true;
245 :         VectorialPointValuePair current = new VectorialPointValuePair(point, objective);
246 :         int iter = 0;
247 :         final ConvergenceChecker<VectorialPointValuePair> checker = getConvergenceChecker();
248 :         while (true) {
249 :             ++iter;
250 : 
251 :             for (int i=0;i<rows;i++) {
252 :                 qtf[i]=weightedResiduals[i];
253 :             }
254 : 
255 :             // compute the Q.R. decomposition of the jacobian matrix
256 :             VectorialPointValuePair previous = current;
257 :             updateJacobian();
258 :             qrDecomposition();
259 : 
260 :             // compute Qt.res
261 :             qTy(qtf);
262 :             // now we don't need Q anymore,
263 :             // so let jacobian contain the R matrix with its diagonal elements
264 :             for (int k = 0; k < solvedCols; ++k) {
265 :                 int pk = permutation[k];
266 :                 weightedResidualJacobian[k][pk] = diagR[pk];
267 :             }
268 : 
269 :             if (firstIteration) {
270 :                 // scale the point according to the norms of the columns
271 :                 // of the initial jacobian
272 :                 xNorm = 0;
273 :                 for (int k = 0; k < cols; ++k) {
274 :                     double dk = jacNorm[k];
275 :                     if (dk == 0) {
276 :                         dk = 1.0;
277 :                     }
278 :                     double xk = dk * point[k];
279 :                     xNorm  += xk * xk;
280 :                     diag[k] = dk;
281 :                 }
282 :                 xNorm = FastMath.sqrt(xNorm);
283 : 
284 :                 // initialize the step bound delta
285 :                 delta = (xNorm == 0) ? initialStepBoundFactor : (initialStepBoundFactor * xNorm);
286 :             }
287 : 
288 :             // check orthogonality between function vector and jacobian columns
289 :             double maxCosine = 0;
290 :             if (cost != 0) {
291 :                 for (int j = 0; j < solvedCols; ++j) {
292 :                     int    pj = permutation[j];
293 :                     double s  = jacNorm[pj];
294 :                     if (s != 0) {
295 :                         double sum = 0;
296 :                         for (int i = 0; i <= j; ++i) {
297 :                             sum += weightedResidualJacobian[i][pj] * qtf[i];
298 :                         }
299 :                         maxCosine = FastMath.max(maxCosine, FastMath.abs(sum) / (s * cost));
300 :                     }
301 :                 }
302 :             }
303 :             if (maxCosine <= orthoTolerance) {
304 :                 // convergence has been reached
305 :                 updateResidualsAndCost();
306 :                 current = new VectorialPointValuePair(point, objective);
307 :                 return current;
308 :             }
309 : 
310 :             // rescale if necessary
311 :             for (int j = 0; j < cols; ++j) {
312 :                 diag[j] = FastMath.max(diag[j], jacNorm[j]);
313 :             }
314 : 
315 :             // inner loop
316 :             for (double ratio = 0; ratio < 1.0e-4;) {
317 : 
318 :                 // save the state
319 :                 for (int j = 0; j < solvedCols; ++j) {
320 :                     int pj = permutation[j];
321 :                     oldX[pj] = point[pj];
322 :                 }
323 :                 double previousCost = cost;
324 :                 double[] tmpVec = weightedResiduals;
325 :                 weightedResiduals = oldRes;
326 :                 oldRes    = tmpVec;
327 :                 tmpVec    = objective;
328 :                 objective = oldObj;
329 :                 oldObj    = tmpVec;
330 : 
331 :                 // determine the Levenberg-Marquardt parameter
332 :                 determineLMParameter(qtf, delta, diag, work1, work2, work3);
333 : 
334 :                 // compute the new point and the norm of the evolution direction
335 :                 double lmNorm = 0;
336 :                 for (int j = 0; j < solvedCols; ++j) {
337 :                     int pj = permutation[j];
338 :                     lmDir[pj] = -lmDir[pj];
339 :                     point[pj] = oldX[pj] + lmDir[pj];
340 :                     double s = diag[pj] * lmDir[pj];
341 :                     lmNorm  += s * s;
342 :                 }
343 :                 lmNorm = FastMath.sqrt(lmNorm);
344 :                 // on the first iteration, adjust the initial step bound.
345 :                 if (firstIteration) {
346 :                     delta = FastMath.min(delta, lmNorm);
347 :                 }
348 : 
349 :                 // evaluate the function at x + p and calculate its norm
350 :                 updateResidualsAndCost();
351 : 
352 :                 // compute the scaled actual reduction
353 :                 double actRed = -1.0;
354 :                 if (0.1 * cost < previousCost) {
355 :                     double r = cost / previousCost;
356 :                     actRed = 1.0 - r * r;
357 :                 }
358 : 
359 :                 // compute the scaled predicted reduction
360 :                 // and the scaled directional derivative
361 :                 for (int j = 0; j < solvedCols; ++j) {
362 :                     int pj = permutation[j];
363 :                     double dirJ = lmDir[pj];
364 :                     work1[j] = 0;
365 :                     for (int i = 0; i <= j; ++i) {
366 :                         work1[i] += weightedResidualJacobian[i][pj] * dirJ;
367 :                     }
368 :                 }
369 :                 double coeff1 = 0;
370 :                 for (int j = 0; j < solvedCols; ++j) {
371 :                     coeff1 += work1[j] * work1[j];
372 :                 }
373 :                 double pc2 = previousCost * previousCost;
374 :                 coeff1 = coeff1 / pc2;
375 :                 double coeff2 = lmPar * lmNorm * lmNorm / pc2;
376 :                 double preRed = coeff1 + 2 * coeff2;
377 :                 double dirDer = -(coeff1 + coeff2);
378 : 
379 :                 // ratio of the actual to the predicted reduction
380 :                 ratio = (preRed == 0) ? 0 : (actRed / preRed);
381 : 
382 :                 // update the step bound
383 :                 if (ratio <= 0.25) {
384 :                     double tmp =
385 :                         (actRed < 0) ? (0.5 * dirDer / (dirDer + 0.5 * actRed)) : 0.5;
386 :                         if ((0.1 * cost >= previousCost) || (tmp < 0.1)) {
387 :                             tmp = 0.1;
388 :                         }
389 :                         delta = tmp * FastMath.min(delta, 10.0 * lmNorm);
390 :                         lmPar /= tmp;
391 :                 } else if ((lmPar == 0) || (ratio >= 0.75)) {
392 :                     delta = 2 * lmNorm;
393 :                     lmPar *= 0.5;
394 :                 }
395 : 
396 :                 // test for successful iteration.
397 :                 if (ratio >= 1.0e-4) {
398 :                     // successful iteration, update the norm
399 :                     firstIteration = false;
400 :                     xNorm = 0;
401 :                     for (int k = 0; k < cols; ++k) {
402 :                         double xK = diag[k] * point[k];
403 :                         xNorm += xK * xK;
404 :                     }
405 :                     xNorm = FastMath.sqrt(xNorm);
406 :                     current = new VectorialPointValuePair(point, objective);
407 : 
408 :                     // tests for convergence.
409 :                     if (checker != null) {
410 :                         // we use the vectorial convergence checker
411 :                         if (checker.converged(iter, previous, current)) {
412 :                             return current;
413 :                         }
414 :                     }
415 :                 } else {
416 :                     // failed iteration, reset the previous values
417 :                     cost = previousCost;
418 :                     for (int j = 0; j < solvedCols; ++j) {
419 :                         int pj = permutation[j];
420 :                         point[pj] = oldX[pj];
421 :                     }
422 :                     tmpVec    = weightedResiduals;
423 :                     weightedResiduals = oldRes;
424 :                     oldRes    = tmpVec;
425 :                     tmpVec    = objective;
426 :                     objective = oldObj;
427 :                     oldObj    = tmpVec;
428 :                 }
429 : 
430 :                 // Default convergence criteria.
431 :                 if ((FastMath.abs(actRed) <= costRelativeTolerance &&
432 :                      preRed <= costRelativeTolerance &&
433 :                      ratio <= 2.0) ||
434 :                     delta <= parRelativeTolerance * xNorm) {
435 :                     return current;
436 :                 }
437 : 
438 :                 // tests for termination and stringent tolerances
439 :                 // (2.2204e-16 is the machine epsilon for IEEE754)
440 :                 if ((FastMath.abs(actRed) <= 2.2204e-16) && (preRed <= 2.2204e-16) && (ratio <= 2.0)) {
441 :                     throw new ConvergenceException(LocalizedFormats.TOO_SMALL_COST_RELATIVE_TOLERANCE,
442 :                             costRelativeTolerance);
443 :                 } else if (delta <= 2.2204e-16 * xNorm) {
444 :                     throw new ConvergenceException(LocalizedFormats.TOO_SMALL_PARAMETERS_RELATIVE_TOLERANCE,
445 :                             parRelativeTolerance);
446 :                 } else if (maxCosine <= 2.2204e-16)  {
447 :                     throw new ConvergenceException(LocalizedFormats.TOO_SMALL_ORTHOGONALITY_TOLERANCE,
448 :                             orthoTolerance);
449 :                 }
450 :             }
451 :         }
452 :     }"

